import{_ as t,o as i,c as o,a0 as a}from"./chunks/framework.DPd3ST4h.js";const u=JSON.parse('{"title":"Runnable review configuration","description":"","frontmatter":{},"headers":[],"relativePath":"runnable-review-configuration.md","filePath":"runnable-review-configuration.md","lastUpdated":1792939911000}'),d={name:"runnable-review-configuration.md"};function n(s,e,r,l,c,h){return i(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="runnable-review-configuration" tabindex="-1">Runnable review configuration <a class="header-anchor" href="#runnable-review-configuration" aria-label="Permalink to &quot;Runnable review configuration&quot;">​</a></h1><p>The GitHub Action passes every value to the review tool through environment variables. This is the interim contract; the parsing in <code>src/review/environment.ts</code> is authoritative. When action-owned indexing is enabled, the action fills the code-context variables from its bundled index action; GitHub Action callers do not provide an artifact path.</p><h2 id="environment-contract" tabindex="-1">Environment contract <a class="header-anchor" href="#environment-contract" aria-label="Permalink to &quot;Environment contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>REDLINE_HARNESS</code></td><td>review mode</td><td><code>echo</code>, <code>pi</code>, or <code>opencode</code>.</td></tr><tr><td><code>REDLINE_REVIEW_DIR</code></td><td>review mode</td><td>Directory holding the context bundle (<code>manifest.json</code>, <code>diffs/</code>, <code>base-files/</code>, …).</td></tr><tr><td><code>REDLINE_SOURCE_DIR</code></td><td>review mode</td><td>Source-at-head export used for head-file context.</td></tr><tr><td><code>REDLINE_OUTPUT_DIR</code></td><td>review mode</td><td>Destination for per-file review records and the summary.</td></tr><tr><td><code>REDLINE_CODE_CONTEXT</code></td><td>optional in review mode</td><td>Path to a bounded <code>code-context.json</code> artifact. Requires <code>REDLINE_CODE_CONTEXT_REPOSITORY</code>.</td></tr><tr><td><code>REDLINE_CODE_CONTEXT_REPOSITORY</code></td><td>with <code>REDLINE_CODE_CONTEXT</code></td><td>Expected <code>owner/name</code> repository identity. Must match the artifact.</td></tr><tr><td><code>REDLINE_MODEL_CONFIG</code></td><td>review mode</td><td>Model configuration JSON (below).</td></tr><tr><td><code>REDLINE_MODEL_AUTH</code></td><td>review mode</td><td>Provider-keyed credential map JSON (below). Not consulted when the model config declares <code>auth: &quot;none&quot;</code>.</td></tr><tr><td><code>REDLINE_FINDING_SCOPE</code></td><td>optional</td><td><code>defects</code> (default) or <code>defects-and-risks</code>.</td></tr><tr><td><code>REDLINE_TIMEOUT</code></td><td>optional</td><td>Per-file model deadline. Duration like <code>4m</code>, <code>10m</code>, or <code>1h30m</code>; default <code>4m</code>, capped at <code>360m</code>.</td></tr><tr><td><code>REDLINE_RUN_TIMEOUT</code></td><td>optional</td><td>Whole-review deadline. Default <code>10m</code>, capped at <code>360m</code>. Each model call is capped by the remaining run budget.</td></tr><tr><td><code>REDLINE_REVIEW_CONCURRENCY</code></td><td>optional</td><td>Maximum simultaneous per-file model calls. Integer from <code>1</code> through <code>8</code>; default <code>4</code>.</td></tr><tr><td><code>REDLINE_REUSE_DIR</code></td><td>optional in review mode</td><td>Action-owned directory for restored and newly validated per-file reuse entries. Requires <code>REDLINE_REUSE_NAMESPACE</code>.</td></tr><tr><td><code>REDLINE_REUSE_NAMESPACE</code></td><td>with <code>REDLINE_REUSE_DIR</code></td><td>Cache identity in <code>owner/name#pull-request</code> form.</td></tr><tr><td><code>REDLINE_VERBOSITY</code></td><td>optional</td><td><code>silent</code> (per-file start/completion lines), <code>progress</code> (bounded activity counts and diagnostics, default), or <code>full-output</code> (readable stream text under a per-file cap).</td></tr></tbody></table><p>Rules enforced by the parser:</p><ul><li>Review inputs must arrive together. A partial selection fails instead of degrading to context-only mode.</li><li>Unknown <code>REDLINE_*</code> variables are rejected, so typos fail loudly.</li><li>Review eligibility is resolved while building the context bundle, before this environment contract is parsed. It comes only from strict trusted-workflow JSON or <code>.redline/review-eligibility.json</code> at the exact base revision; see <a href="/projects/redline/review-eligibility">review eligibility</a>.</li><li>Optional values are validated even without review execution.</li><li>When the whole-review deadline expires, Redline stops starting model calls. It records every remaining reviewed file as an explicit <code>run-deadline-exhausted</code> omission instead of silently dropping coverage.</li><li>Indexed-context path and repository identity arrive together. Configured context that is missing, invalid, stale, unsupported, or unavailable is recorded and degrades to file-only review instead of failing the run.</li><li>Review-reuse directory and namespace arrive together. Restored entries are untrusted and optional; invalid data degrades to normal per-file execution.</li><li>No variable accepts free-form review instructions.</li></ul><h2 id="model-configuration" tabindex="-1">Model configuration <a class="header-anchor" href="#model-configuration" aria-label="Permalink to &quot;Model configuration&quot;">​</a></h2><p><code>REDLINE_MODEL_CONFIG</code> is provider-neutral JSON with three required fields plus one optional auth field:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;provider&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;openrouter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;endpoint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://openrouter.ai/api/v1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;z-ai/glm-5.3-flash&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>provider</code> — a short identifier, <code>[A-Za-z0-9._-]</code>, at most 64 characters. It keys the credential map and names the provider inside harness configuration.</li><li><code>endpoint</code> — absolute <code>http</code> or <code>https</code> URL of an OpenAI-compatible API. Loopback endpoints are permitted for local model servers and the CI mock endpoint.</li><li><code>model</code> — the model identifier understood by the endpoint, at most 256 characters.</li><li><code>auth</code> — optional; the only supported value is <code>&quot;none&quot;</code>, the credential-less profile for endpoints that need no authentication. See <a href="#local-model-runners">local model runners</a>.</li></ul><p>There is no fixed-model allowlist and no provider-specific credential input.</p><h2 id="credential-map" tabindex="-1">Credential map <a class="header-anchor" href="#credential-map" aria-label="Permalink to &quot;Credential map&quot;">​</a></h2><p><code>REDLINE_MODEL_AUTH</code> maps provider names to credential values:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;openrouter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-or-v1-…&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Only the entry for the configured provider is selected; everything else stays host-side. The selected credential reaches the harness through the mechanism documented in <a href="/projects/redline/harness-executor">harness executor</a> — an environment variable for Pi, a mode-0600 generated config file for OpenCode — and never appears in prompts, logs, diagnostics, or published output.</p><p>When the model config declares <code>&quot;auth&quot;: &quot;none&quot;</code>, the credential map is not required and <strong>not consulted</strong>: no credential is selected and nothing reaches the harness. A supplied map is tolerated (not an error) because the action&#39;s review gate requires a non-empty <code>model-auth</code>; pass a placeholder map there.</p><h2 id="local-model-runners" tabindex="-1">Local model runners <a class="header-anchor" href="#local-model-runners" aria-label="Permalink to &quot;Local model runners&quot;">​</a></h2><p>Local runners that expose an OpenAI-compatible REST endpoint work through the same contract, with the credential-less profile — no paid API key involved:</p><table tabindex="0"><thead><tr><th>Runner</th><th>Endpoint</th><th>Model id</th></tr></thead><tbody><tr><td>Ollama</td><td><code>http://127.0.0.1:11434/v1</code></td><td><code>name:tag</code>, for example <code>qwen3:0.6b</code></td></tr><tr><td>LM Studio</td><td><code>http://127.0.0.1:1234/v1</code></td><td>model identifier shown in the server tab</td></tr><tr><td>llama.cpp server</td><td><code>http://127.0.0.1:8080/v1</code></td><td><code>-m</code> model name or <code>-a</code> alias</td></tr><tr><td>vLLM</td><td><code>http://&lt;host&gt;:8000/v1</code></td><td>served model name</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_MODEL_CONFIG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{&quot;provider&quot;:&quot;ollama&quot;,&quot;endpoint&quot;:&quot;http://127.0.0.1:11434/v1&quot;,&quot;model&quot;:&quot;qwen3:0.6b&quot;,&quot;auth&quot;:&quot;none&quot;}&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_MODEL_AUTH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&#39;</span></span></code></pre></div><p>Notes:</p><ul><li>Each runner mounts the OpenAI-compatible API under <code>/v1</code> — include the suffix.</li><li>Loopback (<code>127.0.0.1</code>, <code>localhost</code>) and private-network endpoints are accepted by the same endpoint validation as remote APIs.</li><li>A server that still checks the header (rare) instead takes a placeholder entry in <code>REDLINE_MODEL_AUTH</code>; the value is local-only.</li><li>Via the GitHub Action, keep supplying <code>model-auth</code> (a placeholder map) — the action&#39;s review gate requires it, and with <code>auth: &quot;none&quot;</code> the map is not consulted, so no credential reaches the harness.</li><li>Self-hosted CI runners can reach the local server directly, which is the intended production shape for private projects. The container-sandbox milestone will revisit isolation for untrusted environments.</li></ul><h2 id="cli-usage" tabindex="-1">CLI usage <a class="header-anchor" href="#cli-usage" aria-label="Permalink to &quot;CLI usage&quot;">​</a></h2><p>The same contract drives the standalone CLI:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/review/cli.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --validate-only</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # validate the environment only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/review/cli.ts</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # run the review</span></span></code></pre></div><p>For standalone CLI use, opt into indexed context by setting both variables before running the review:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_CODE_CONTEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/absolute/path/code-context.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_CODE_CONTEXT_REPOSITORY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">owner/repository</span></span></code></pre></div><p>The review tool verifies repository and head identity, parses the exact artifact schema, and re-resolves each selected span from <code>REDLINE_SOURCE_DIR</code>. It never opens the provider database or invokes the provider.</p><p>Exit codes: <code>0</code> success (context-only or completed review), <code>1</code> review or bundle failure, <code>2</code> usage or validation failure. A review run exits <code>1</code> when no reviewed file produced a validated review — every file failed, timed out, or produced invalid output.</p>`,29)])])}const E=t(d,[["render",n]]);export{u as __pageData,E as default};
